import sys

def count_equivalence_classes(S):
    n = len(S)
    seen = set()
    for i in range(n):
        count_ones = 0
        for j in range(i, n):
            count_ones += (S[j] == '1')
            key = (j - i + 1, count_ones % 2)
            seen.add(key)
    return len(seen)

input = sys.stdin.read().splitlines()
T = int(input[0])
results = []
for i in range(1, T + 1):
    S = input[i]
    results.append(count_equivalence_classes(S))
for result in results:
    print(result)
